package com.hau.exam.application.service;import com.hau.exam.application.port.out.*;import com.hau.exam.domain.exception.NotFoundException;import com.hau.exam.domain.model.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class TemplateService{private final ExamTemplateRepository repo;private final ExamMatrixRepository matrices;private final Clock clock;public TemplateService(ExamTemplateRepository r,ExamMatrixRepository m,Clock c){repo=r;matrices=m;clock=c;}@Transactional public ExamTemplate create(String name,UUID matrixId,String header,String instructions,Actor a){var m=matrices.findById(matrixId).orElseThrow(()->new NotFoundException("Exam matrix not found"));MatrixService.scope(a,m.facultyId());Instant n=Instant.now(clock);return repo.save(new ExamTemplate(UUID.randomUUID(),name,m.facultyId(),matrixId,header,instructions,a.userId(),n,n));}@Transactional(readOnly=true)public ExamTemplate get(UUID id,Actor a){var t=repo.findById(id).orElseThrow(()->new NotFoundException("Exam template not found"));MatrixService.scope(a,t.facultyId());return t;}}
